import { guideLesson } from './define.ts';
import type { Lesson } from './types.ts';
const P = (slug: string, title: string, prerequisites: string[], objectives: string[], sections: Lesson['sections'], question: string, options: string[], answer: number, explanation: string): Lesson => guideLesson('plat', slug, { title, description: objectives.join(' · '), minutes: 45, prerequisites, objectives, sections, quiz: { question, options, answer, explanation } });
export const platinumLessons: Lesson[] = [
P('segtree-ext',"Árboles de segmentos: buscar posiciones y combinar datos",['usaco-gold-purs'],["Encontrar una posición descendiendo por el árbol","Guardar resúmenes que se puedan combinar por intervalos"],[
{title:"El primer salón donde cabe un grupo",body:"Tienes cuatro salones con capacidades libres [2,7,1,5]. Llega un grupo de cuatro personas y debes asignarle el primer salón donde quepa. Recorrer las capacidades de izquierda a derecha encuentra la respuesta, pero repetir ese recorrido para muchos grupos puede costar O(nq).\n\nUn árbol de segmentos puede guardar el máximo de cada intervalo. Ese dato responde una pregunta concreta: si el máximo es menor que cuatro, ninguna posición del intervalo sirve. No necesitamos conocer todas sus capacidades para descartarlo. Usaremos índices desde cero e intervalos [l,r), que incluyen l y excluyen r."},
{title:"Un resumen que permite descartar una mitad",body:"La mitad izquierda contiene [2,7] y guarda máximo 7; la derecha contiene [1,5] y guarda 5. La raíz combina ambos máximos y también guarda 7. Como 7≥4, sabemos que existe un salón adecuado.\n\nMira primero al hijo izquierdo. Si su máximo alcanza el tamaño del grupo, baja allí: cualquier respuesta de esa mitad aparece antes que las de la derecha. Si no alcanza, descarta toda la mitad izquierda y entra en la derecha. Repite hasta llegar a una hoja. Cada decisión usa el resumen de un hijo; no hace falta una búsqueda binaria que consulte intervalos completos."},
{title:"Qué ocurre al llegar varios grupos",body:"Para el grupo de cuatro, entramos en [2,7], descartamos la capacidad 2 y elegimos el índice 1. Al ocuparlo, queda [2,3,1,5]. Recalculamos los máximos desde esa hoja hasta la raíz: el máximo izquierdo pasa a 3 y el total a 5.\n\nUn grupo de tres vuelve a usar el índice 1 y deja [2,0,1,5]. Uno de seis no cabe: basta comparar seis con el máximo 5 de la raíz. Elegir el salón de capacidad cinco para el primer grupo habría dejado menos espacio sobrante, pero no cumpliría la regla del primer salón. La prioridad por la izquierda forma parte del problema."},
{title:"Del ejemplo al programa",body:"El programa siguiente coloca las hojas en un arreglo cuya longitud es una potencia de dos. Las hojas sobrantes tienen capacidad cero. Como los grupos son positivos, esas hojas nunca pueden ser elegidas. Los índices internos empiezan en cero, pero imprimimos posiciones desde uno para reservar la salida cero cuando no existe salón.\n\nLas capacidades y sumas deben caber en el tipo elegido; long long evita problemas al sumar muchos valores grandes. Para revisar la implementación, compara cada grupo con un recorrido directo en arreglos pequeños. Incluye capacidad cero, un único salón, grupos repetidos y un grupo mayor que el máximo. Para el resumen de subarreglos, prueba también valores todos negativos."}
],"En [2,7,1,5], ¿cuál es la primera posición con capacidad al menos 4, contando desde cero?",['0','1','2','3'],1,"La posición 0 contiene 2 y no alcanza. La posición 1 contiene 7 y sí alcanza; el máximo de la mitad izquierda permite dirigir allí la búsqueda."),
P('range-sweep',"Consultas con barridos y eventos",['usaco-gold-purs','usaco-silver-sorting-custom'],["Ordenar una coordenada para mantener activos los datos necesarios","Decidir el orden de eventos que coinciden"],[
{title:"Contar puntos sin construir una tabla enorme",body:"Tenemos los puntos (1,1), (2,3), (3,2) y otra copia de (2,3). Queremos responder cuántos quedan dentro de varios rectángulos. Comparar cada punto con cada consulta cuesta O(nq). Una estructura bidimensional puede resolverlo, pero aquí sabemos todas las consultas de antemano y podemos aprovechar su orden.\n\nEmpezaremos por F(X,Y): cuántos puntos cumplen x≤X e y≤Y. Ordenaremos por el límite X y mantendremos los valores y de los puntos que ya cumplan la primera condición. Este recorrido se llama barrido. Como procesa consultas en otro orden, guarda sus identificadores para devolver cada respuesta a su lugar."},
{title:"El conjunto que debe estar disponible",body:"Ordena puntos por x y preguntas por X. Antes de responder una pregunta, avanza por los puntos mientras x≤X y agrega uno en el Fenwick correspondiente a cada y. Después consulta el prefijo hasta Y.\n\nEn ese momento, Fenwick contiene todos y solo los puntos que cumplen x≤X. Esa es la condición que debe mantener el barrido. El prefijo añade la segunda condición, y≤Y. Una igualdad en la frontera cuenta; usar x<X excluiría puntos válidos. Dos puntos coincidentes también cuentan dos veces, así que cada copia realiza su propio incremento."},
{title:"El límite horizontal avanza; el vertical puede variar",body:"Con X=1 solo entró (1,1), por lo que F(1,3)=1. Cuando X pasa a dos, agregamos las dos copias de (2,3). Ahora F(2,2)=1, pero F(2,3)=3. Al llegar a X=3, entra (3,2) y F(3,2)=2.\n\nY puede aumentar o disminuir entre preguntas: solo cambia qué prefijo consultamos, no qué puntos guardamos. X sí avanza siempre, porque ordenamos las preguntas. De ese modo cada punto entra una sola vez y no necesitamos retirarlo para responder una consulta con un límite horizontal anterior."},
{title:"Cuándo el orden original sí importa",body:"Si la siguiente consulta se calcula usando la respuesta anterior, todavía no conoces sus límites y no puedes ordenar todos los eventos al inicio. También debes revisar el modelo si los puntos aparecen o desaparecen durante el tiempo original del problema. Reordenar solo es válido cuando conserva las consultas y sus datos.\n\nEl ejercicio limita las coordenadas a [−10⁹,10⁹]; restar uno en long long no desborda. Comprueba puntos sobre los cuatro bordes, puntos repetidos, coordenadas negativas y rectángulos vacíos de puntos. Un recorrido directo sobre todos los puntos sirve para comparar respuestas en instancias pequeñas."}
],"Un horizontal puede tocar los extremos de un vertical. A igual altura, ¿en qué orden procesas sus eventos?",['Salida, consulta, entrada','Consulta, entrada, salida','Entrada, consulta, salida'],2,"Primero agrega los verticales que empiezan, después responde los horizontales y al final retira los verticales que terminan. Así la consulta incluye ambos extremos."),
P('RURQ',"Cambios y sumas sobre intervalos",['usaco-gold-purs','usaco-plat-segtree-ext'],["Obtener sumas de rango con dos árboles Fenwick","Combinar cambios pendientes en el orden correcto"],[
{title:"Sumar a varias posiciones y preguntar por su suma",body:"Partimos de [2,5,1,3] y queremos agregar cuatro a las posiciones 2 y 3. El arreglo debe quedar [2,9,5,3]. Con un Fenwick de actualizaciones puntuales podemos cambiar ambas posiciones, pero una operación podría afectar casi todo el arreglo. Hacerlo posición por posición costaría O(n log n).\n\nBuscamos que el trabajo dependa de los extremos del intervalo, no de su longitud. Para sumas, las diferencias permiten construir una solución con dos Fenwick. Un árbol de segmentos con modificaciones pendientes resuelve el mismo problema y admite otras operaciones. Aquí los índices empiezan en uno y [l,r] incluye ambos extremos."},
{title:"Dos marcas bastan para describir un incremento",body:"Define D[1]=A[1] y D[i]=A[i]−A[i−1] para i>1. Sumando D[1] hasta D[i] recuperas A[i], porque las diferencias intermedias se cancelan. Nuestro arreglo [2,5,1,3] produce D=[2,3,-4,2].\n\nAl sumar cuatro en [2,3], solo cambia la diferencia donde empieza el aumento y donde termina: D[2]+=4 y D[4]−=4. Queda [2,7,-4,-2], cuyos prefijos reconstruyen [2,9,5,3]. En general, agregar x a [l,r] modifica D[l]+=x y D[r+1]−=x, si r<n. Ya podemos actualizar un rango y consultar un punto; falta obtener sumas de rangos."},
{title:"Contar cuántas veces aparece cada diferencia",body:"Queremos S(p)=A[1]+…+A[p]. Sustituye cada valor por su suma de diferencias. D[j] aparece en A[j], A[j+1] y hasta A[p]: participa p−j+1 veces. Por tanto, S(p)=Σ(j≤p)(p−j+1)D[j]=p·ΣD[j]−Σ(j−1)D[j].\n\nUn Fenwick B1 guarda D[j] y otro B2 guarda (j−1)D[j]. Para cambiar una diferencia en delta, agrega delta a B1 y delta·(j−1) a B2. La consulta de prefijo es p·B1.sum(p)−B2.sum(p). Finalmente, la suma de [l,r] es S(r)−S(l−1). Los dos árboles representan los dos términos de la identidad."},
{title:"Límites e implementación",body:"Ambas estructuras usan O(n) memoria y O(log n) por operación. Dos Fenwick requieren menos casos de implementación para este problema; el árbol diferido permite otros resúmenes y etiquetas si puedes definir cómo se aplican y componen. No sustituyas suma por mínimo en las fórmulas de Fenwick: su derivación utiliza restas y distribución.\n\nUsa long long para los productos y resultados. Con 200000 posiciones, 200000 operaciones y aumentos de hasta 10⁶, el total puede acercarse a 4·10¹⁶. El programa empieza en ceros; para un arreglo inicial puedes cargar sus diferencias. Revisa intervalos de una posición, ambos extremos del arreglo, aumentos negativos y consultas sin actualizaciones previas."}
],"El arreglo empieza en ceros. Si sumas 3 a las posiciones 2…4, ¿cuánto suma el intervalo 1…4?",['3','6','9','12'],2,"Las posiciones 2, 3 y 4 pasan a valer 3; la primera sigue en cero. La suma pedida es 0+3+3+3=9."),
P('sparse-segtree','Árboles de segmentos dispersos',['usaco-plat-segtree-ext'],["Crear solo los nodos que necesitan los cambios","Elegir entre un dominio implícito y coordenadas comprimidas"],[
{title:"Contadores muy separados",body:"Tienes contadores en las posiciones de 0 a 10¹²−1. Empiezan en cero y solo habrá 5000 cambios, aunque las consultas puedan abarcar cualquier intervalo. Reservar un arreglo para todas las posiciones no cabe en memoria. Lo que sí podemos guardar son las partes del dominio que llegan a cambiar.\n\nUn árbol de segmentos disperso divide el dominio igual que uno ordinario, pero crea nodos conforme los necesita. Para verlo, usaremos U=16 y el intervalo [0,16): sus hijos son [0,8) y [8,16). Repetir estas divisiones lleva hasta intervalos de una posición. Incluso con U=10¹², la altura ronda cuarenta."},
{title:"Un intervalo sin cambios no necesita un nodo",body:"Como todos los contadores empiezan en cero, un hijo que no existe representa una suma conocida: cero. Una consulta puede devolverla sin construir ese hijo. La raíz también puede empezar ausente.\n\nCada nodo creado guarda suma e índices de sus hijos. Podemos usar −1 para indicar ausencia y un vector para almacenar los demás. El índice dentro del vector identifica el nodo, pero no es una coordenada del problema. Por ejemplo, nodos[12] podría representar [500000,1000000). La recursión lleva sus límites como parámetros y usa los índices únicamente para localizar la información almacenada."},
{title:"Crear solo el camino que cambia",body:"Para agregar cinco en la posición 13, visitamos [0,16), [8,16), [12,16), [12,14) y [13,14). Creamos los nodos ausentes de ese camino. En la hoja sumamos cinco; al regresar, cada padre suma sus hijos, tomando cero para los que no existen.\n\nEn general, divide [L,R) en m=L+(R−L)/2. Si x<m, actualiza el hijo izquierdo; en caso contrario, el derecho. Una actualización posterior en 12 comparte el camino hasta [12,14) y solo necesita una hoja distinta. Los caminos compartidos explican por qué el número real de nodos puede ser menor que cambios por altura."},
{title:"Tiempo, memoria y cambios de rango",body:"Actualizar una posición y consultar un intervalo cuesta O(log U). Una consulta solo mantiene dos fronteras parcialmente cubiertas por nivel; los demás nodos visitados aportan su suma completa. Con q actualizaciones se crean como máximo O(q log U) nodos. Las consultas no aumentan ese consumo. Usa long long para coordenadas y sumas y calcula el punto medio mediante L+(R−L)/2.\n\nSi agregas modificaciones de rango con etiquetas pendientes, debes definir qué hereda un hijo que se crea después del cambio. Ya no puedes interpretar todo hijo ausente como cero. Para la versión puntual, revisa posiciones 0 y U−1, incrementos negativos y consultas donde no haya ocurrido ningún cambio."}
],"En un árbol disperso de sumas, todos los valores empiezan en cero. ¿Qué significa un hijo que todavía no existe?",['Un error de memoria','Un intervalo cuya suma es cero','Una suma desconocida'],1,"Ninguna actualización ha necesitado ese intervalo y sus valores siguen en cero. Puedes devolver suma cero sin crear el nodo."),
P('2DRQ',"Consultas de rectángulos en dos dimensiones",['usaco-gold-purs','usaco-silver-more-prefix-sums'],["Combinar prefijos para sumar rectángulos","Calcular la memoria necesaria para un Fenwick bidimensional"],[
{title:"La suma de una parte de la tabla",body:"Tenemos una matriz con filas [1,2,3], [4,5,6] y [7,8,9]. Queremos sumar el bloque inferior derecho: 5+6+8+9=28. Recorrer sus celdas funciona, pero hacerlo para muchos rectángulos puede repetir casi toda la tabla en cada consulta.\n\nDefinimos P(x,y) como la suma desde la esquina superior izquierda hasta la fila x y la columna y, incluidas. Numeramos desde uno y reservamos P(0,y)=P(x,0)=0. Con esos prefijos podemos recortar cualquier rectángulo, incluso cuando toca la primera fila o la primera columna."},
{title:"Recortar con cuatro prefijos",body:"P(x2,y2) incluye el rectángulo pedido y también las filas anteriores a x1 y las columnas anteriores a y1. Quitamos las primeras con P(x1−1,y2) y las segundas con P(x2,y1−1). La esquina común se quitó dos veces, así que la reponemos con P(x1−1,y1−1).\n\nLa respuesta es P(x2,y2)−P(x1−1,y2)−P(x2,y1−1)+P(x1−1,y1−1). En el ejemplo obtenemos 45−6−12+1=28. Una celda interior participa una vez; una celda en las franjas se cancela; en la esquina, su coeficiente es 1−1−1+1=0. La misma cuenta sirve con valores negativos."},
{title:"Preparar prefijos cuando no hay cambios",body:"Cada prefijo se construye con P(x,y)=A[x][y]+P(x−1,y)+P(x,y−1)−P(x−1,y−1). Sumamos la celda actual, la parte de arriba y la parte de la izquierda, y corregimos su esquina compartida. Si recorremos por filas, esos tres resultados ya están calculados.\n\nPreparar y guardar toda la tabla cuesta O(nm); cada consulta posterior usa cuatro lecturas y cuesta O(1). El inconveniente aparece al modificar una celda: muchos prefijos la contienen. Si cambiamos el centro de cinco a quince, el bloque del ejemplo pasa de 28 a 38, pero habría que corregir varios prefijos almacenados."},
{title:"Convenciones que debe respetar el código",body:"Fenwick recibe incrementos, no asignaciones. Para cambiar una celda de anteriorValor a nuevoValor, envía nuevoValor−anteriorValor. El ejercicio siguiente pide incrementos explícitos. Los índices empiezan en uno: iniciar una actualización en cero produciría un ciclo, porque lowbit(0)=0 y la posición nunca avanzaría.\n\nRevisa una matriz 1×1, consultas de una celda, rectángulos pegados a los bordes e incrementos negativos. Usa long long para las sumas: una celda puede caber en int aunque la tabla completa no. Si los datos nunca cambian, los prefijos estáticos ya responden en O(1) y no necesitan el trabajo adicional de Fenwick."}
],"Las filas de una matriz son [1,2,3], [4,5,6] y [7,8,9]. ¿Cuánto suma su bloque inferior derecho de 2×2?",['24','26','28','30'],2,"El bloque contiene 5, 6, 8 y 9, cuya suma es 28. Con prefijos obtienes lo mismo: 45−6−12+1=28."),
P('DC-SRQ',"Consultas estáticas con bloques disjuntos",['usaco-gold-lca-euler','usaco-plat-segtree-ext'],["Combinar intervalos sin necesitar una operación inversa","Respetar el orden en operaciones como composición"],[
{title:"Componer un intervalo de funciones",body:"Una fila contiene funciones que se aplican de izquierda a derecha. Queremos preparar la fila para consultar cualquier intervalo sin ejecutar sus funciones una por una. Con sumas podríamos restar prefijos; con funciones no siempre existe una operación que deshaga un prefijo. Una función constante f(x)=7, por ejemplo, pierde el argumento original.\n\nLa composición sí es asociativa: podemos agrupar funciones consecutivas sin cambiar el orden en que actúan. Aprovecharemos esa propiedad en una tabla disjunta para datos fijos. Durante la explicación usamos posiciones desde cero e intervalos inclusivos [l,r]. No admitiremos actualizaciones sobre la fila preparada."},
{title:"Dos resúmenes alrededor de un corte",body:"Divide [L,R] entre M y M+1. En la mitad izquierda prepara los sufijos que terminan en M: A[i]⊗…⊗A[M]. En la derecha prepara los prefijos que empiezan en M+1: A[M+1]⊗…⊗A[j].\n\nSi l≤M<r, la respuesta es sufijo[l]⊗prefijo[r]. Son dos fragmentos consecutivos, separados y con unión exacta [l,r]. Si la consulta cabe entera en una mitad, repite el procedimiento allí. Cualquier intervalo de más de un elemento termina cruzando un corte; un intervalo de una posición devuelve directamente su elemento."},
{title:"El orden dentro de cada resumen",body:"Construye sufijos de derecha a izquierda con suf[i]=A[i]⊗suf[i+1]. Construye prefijos de izquierda a derecha con pre[i]=pre[i−1]⊗A[i]. Aunque ambos recorridos agreguen un elemento, lo agregan en extremos distintos y no debes intercambiar los operandos.\n\nPara f(x)=2x+1 y g(x)=3x, aplicar f y luego g da 6x+3. Invertirlas da 6x+1. Representamos una función afín como (a,b) y definimos combinar(f,g)=g∘f. Si f=(a,b) y g=(c,d), el resultado es (c·a,c·b+d). Así el orden del arreglo coincide con el orden de aplicación."},
{title:"Otra forma de repartir consultas conocidas",body:"Si ya conoces todas las preguntas, puedes resolverlas por divide y vencerás: en cada bloque contesta las que cruzan el centro y reparte las demás entre sus mitades. Una versión directa tarda O((n+q) log n) y puede liberar resúmenes después de usarlos. La tabla disjunta conserva más información para contestar preguntas posteriores inmediatamente.\n\nEl ejercicio calcula coeficientes módulo 1000000007 e incluye funciones constantes, que no tienen inversa. Revisa tamaños que no sean potencias de dos: el último bloque puede estar incompleto y sus bucles deben detenerse en n. Comprueba también consultas unitarias y funciones cuyo orden cambie el resultado."}
],"¿Qué propiedad necesita la operación que combina los bloques de una tabla disjunta?",['Conmutatividad e inverso','Asociatividad','Idempotencia obligatoria'],1,"Los bloques no se superponen y se combinan en su orden original. Basta que la operación sea asociativa: reagrupar no cambia el resultado."),
P('sqrt',"Bloques y algoritmo de Mo",['usaco-gold-purs','usaco-silver-sorting-custom'],["Elegir un tamaño de bloque contando su trabajo","Reutilizar frecuencias al mover una ventana de consulta"],[
{title:"Sumar grupos completos y revisar las orillas",body:"En [1,2,3,4,5,6,7,8,9], guarda sumas de bloques de tres: 6,15,24. Para consultar [1,7] con índices desde cero, suma las posiciones de valores dos y tres, usa el bloque completo de suma quince y agrega siete y ocho. Obtienes 35 sin revisar cada valor del bloque central.\n\nCon bloques de tamaño B, una consulta recorre como máximo dos orillas de B elementos y unos n/B bloques completos. Su costo es O(B+n/B). Elegir B cerca de √n equilibra ambos trabajos. Si cambian las operaciones o su frecuencia, conviene volver a calcular ese equilibrio."},
{title:"Qué se modifica al cambiar una posición",body:"Si A[i] cambia a v, la suma de su bloque aumenta v−A[i]. Guardamos ese nuevo valor y ajustamos un solo resumen, así que la actualización cuesta O(1). No necesitamos volver a recorrer todo el bloque para sumas.\n\nCon otros resúmenes puede ser distinto. Si guardamos el mínimo y reemplazamos precisamente el elemento mínimo por uno mayor, quizá debamos revisar los demás valores del bloque. La división en bloques organiza los datos, pero no garantiza por sí sola el mismo costo para cualquier pregunta. Primero determina cómo reconstruir el resumen afectado."},
{title:"Cuando no basta combinar resúmenes pequeños",body:"Para contar valores distintos, no podemos sumar los distintos de dos bloques: el mismo valor podría aparecer en ambos. Unir conjuntos completos en cada consulta puede ser costoso. Mo evita esa combinación y mantiene una sola ventana, con frecuencias de los valores que contiene.\n\nGuarda freq[v] y distintos. Al agregar v, aumenta distintos solo si su frecuencia era cero; después incrementa freq[v]. Al quitarlo, disminuye su frecuencia y reduce distintos solo si quedó en cero. Así una segunda copia no crea un valor distinto ni quitar una copia elimina las demás."},
{title:"Condiciones de uso y comprobaciones",body:"La versión básica necesita un arreglo fijo y todas las consultas disponibles al empezar. Cambios intercalados requieren otra variante, capaz de aplicar y deshacer modificaciones. Si las consultas dependen de respuestas anteriores, tampoco puedes reordenarlas directamente.\n\nAntes de ordenar, comprueba agregar y quitar moviendo una ventana a mano. Después compara el algoritmo completo con construir un conjunto por consulta en datos pequeños. Incluye valores todos iguales, todos distintos, ventanas de una posición y consultas repetidas. Para sumas con cambios puntuales, Fenwick suele ser más directo; Mo resulta útil cuando la respuesta depende de frecuencias difíciles de combinar."}
],"En [1,2,1,3], toma las posiciones 1…3 contando desde cero. ¿Cuántos valores distintos contienen?",['2','3','4'],1,"El intervalo es [2,1,3]. Sus tres elementos tienen valores diferentes, así que la respuesta es 3."),
P('binary-jump','Saltos binarios y ancestros',['usaco-silver-intro-tree','usaco-silver-func-graphs'],["Preparar saltos de longitudes que son potencias de dos","Encontrar ancestros y el primer ancestro compartido"],[
{title:"Consultar muchos saltos de una vez",body:"Supón que cada ciudad tiene una salida indicada y quieres saber dónde terminarás después de k viajes. Seguir la salida k veces funciona, pero una consulta con k=10¹⁸ no cabe en una ejecución. En cambio, puedes guardar de antemano el destino de viajes de 1, 2, 4, 8 y más pasos.\n\nLlamamos sucesor al destino de un solo paso. En un árbol puede ser el padre de cada vértice; en un grafo funcional, cada vértice tiene exactamente un sucesor. El mismo procedimiento sirve para ambos, aunque el grafo tenga ciclos."},
{title:"Construir saltos a partir de otros saltos",body:"Define up[j][v] como el destino después de 2^j pasos desde v. La primera fila contiene los sucesores: up[0][v]=sucesor(v). Para construir la siguiente, haz dos saltos de la longitud anterior: up[j][v]=up[j−1][up[j−1][v]].\n\nEn la cadena 5→4→3→2→1→0, el salto de dos pasos desde 5 termina en 3. El de cuatro termina en 1, porque encadena dos saltos de dos. Calcula una fila completa antes de usarla para construir la siguiente."},
{title:"Responder una distancia escrita en binario",body:"La distancia 13 se escribe 8+4+1. Por eso, una consulta de trece pasos necesita únicamente los saltos de esas tres longitudes. Recorre los bits de k; si el bit j vale uno, cambia v por up[j][v]. Con k=0 no haces ningún salto.\n\nCada movimiento sustituye una parte exacta del recorrido. La suma de las longitudes elegidas es k y todas siguen la misma función sucesor, así que el resultado coincide con avanzar uno por uno. En el ciclo 0→1→2→0, ocho pasos desde 0 terminan en 2."},
{title:"Costo de preparar y consultar",body:"Para n vértices y saltos de hasta K, preparar y guardar la tabla cuesta O(n log K). Cada consulta examina O(log K) bits. Si solo buscas ancestros existentes y LCA en un árbol, K≤n y las cotas se expresan con log n.\n\nComprueba primero distancias pequeñas contra un recorrido de un paso a la vez. Después prueba k=0, un salto mayor que la profundidad y un número grande de vueltas en un ciclo conocido. Esas pruebas distinguen errores de consulta, de tamaño de tabla y de la convención elegida para la raíz."}
],"¿Qué potencias de dos suman trece y permiten hacer ese recorrido con saltos binarios?",['8,4,1','8,3,2','4,4,4,1','16,−3'],0,"13=8+4+1. Su representación binaria 1101 indica que necesitas esos tres saltos."),
P('merging',"Unir contenedores de pequeño a grande",['usaco-gold-dp-trees','usaco-gold-intro-sorted-sets'],["Contar cuántas veces se mueve cada elemento","Reutilizar conjuntos para responder por subárbol"],[
{title:"Contar colores debajo de cada vértice",body:"Tienes un árbol con un color en cada vértice y quieres saber cuántos colores distintos hay en cada subárbol. Puedes resolver a los hijos y unir sus conjuntos en el padre. El resultado es correcto, pero copiar todos los conjuntos desde cero puede repetir demasiadas inserciones.\n\nEn una cadena con colores distintos, el padre copiaría un conjunto de tamaño 1, luego otro de tamaño 2, y así hasta n. La suma es cuadrática. Para evitarlo, conserva uno de los conjuntos y agrega en él los elementos de los otros."},
{title:"Reutilizar el conjunto de un hijo",body:"La técnica de pequeño a grande conserva un contenedor grande y recorre los pequeños para incorporar sus elementos. Cuando todos los elementos son distintos, cada elemento trasladado termina en un conjunto al menos dos veces mayor. Ese tamaño solo puede duplicarse O(log n) veces.\n\nCon colores repetidos, una unión no necesariamente duplica el número de claves. Para no apoyar la demostración en esa afirmación falsa, aquí elegiremos el hijo con más vértices en su subárbol. Su conjunto se reutiliza y el trabajo de los demás se cuenta por vértices."},
{title:"Una unión con colores repetidos",body:"Supón que dos hijos aportan {rojo,azul,verde} y {azul,amarillo}, y la raíz es roja. Al incorporar el segundo conjunto al primero, azul ya existe y amarillo se agrega. Insertar después rojo tampoco modifica el conjunto. El resultado tiene cuatro colores.\n\nGuarda la respuesta numérica de cada hijo antes de reutilizar su contenedor. Ese conjunto puede crecer al procesar al padre y dejar de representar el subárbol original, pero el número que ya guardaste sigue siendo correcto. Conservar todos los conjuntos históricos exigiría otro diseño."},
{title:"Implementación y casos que conviene comprobar",body:"Con set y liberando los contenedores transferidos, el tiempo es O(n log²n) y los datos activos ocupan O(n) memoria. Para evitar una recursión demasiado profunda en una cadena, puedes construir un orden de visita con un vector y procesarlo al revés, como hace el ejercicio.\n\nPrueba todos los colores iguales, todos diferentes, una cadena y una estrella. En una cadena no hay mezclas ligeras: cada vértice inserta su color en el conjunto reutilizado. En una estrella, la raíz incorpora muchos conjuntos de una clave. Ambos casos deben producir la misma respuesta que contar directamente cada subárbol."}
],"Para unir conjuntos de tamaños 3 y 20 con la técnica de pequeño a grande, ¿qué operación eliges?",['Insertar los 20 elementos en el de 3','Insertar los 3 elementos en el de 20','Copiar ambos a dos conjuntos nuevos'],1,"Conserva el conjunto de 20 e inserta en él las tres claves del pequeño. Así recorres el contenedor menor y reutilizas los datos que ya están en el grande."),
P('hld',"Descomposición pesada y ligera de árboles",['usaco-gold-tree-euler','usaco-plat-segtree-ext'],["Convertir un camino en pocos intervalos","Consultar y cambiar valores usando esa descomposición"],[
{title:"Consultar valores a lo largo de un camino",body:"Supón que cada vértice de un árbol tiene un valor. Quieres cambiar valores y sumar los del camino entre dos vértices. Recorrer el camino completo responde una consulta, pero en una cadena puede visitar n vértices cada vez.\n\nUn recorrido DFS convierte los subárboles en intervalos de un arreglo; un camino arbitrario puede atravesar varias ramas y no ocupa necesariamente un intervalo. La descomposición pesada y ligera, llamada HLD, lo divide en unos pocos tramos que sí puedes consultar como intervalos."},
{title:"Escoger qué cadenas conservar juntas",body:"Para cada vértice, elige como pesado a un hijo cuyo subárbol tenga el mayor tamaño. Los demás hijos son ligeros. Las aristas pesadas se encadenan y forman caminos sin bifurcaciones; cada uno será una cadena.\n\nUna arista ligera entra en un subárbol de tamaño menor que la mitad del actual: hay otro hijo al menos igual de grande. Por eso una ruta desde la raíz cruza O(log n) aristas ligeras. Esta propiedad vale incluso cuando el árbol original es una cadena o está muy desequilibrado."},
{title:"Asignar posiciones a los vértices",body:"Calcula primero padres, profundidades y tamaños. Después numera los vértices visitando siempre al hijo pesado antes que a los ligeros. Guarda pos[v], su posición, y head[v], la cabeza de su cadena. El hijo pesado conserva la cabeza de su padre; cada hijo ligero inicia una nueva.\n\nAsí, todos los vértices de una cadena quedan consecutivos y ordenados por profundidad. Si el árbol es 1–2–3–4–5, puede tener una única cadena: el camino 2–5 ocupa las cuatro posiciones consecutivas correspondientes. Coloca los valores en ese arreglo y prepara un Fenwick o árbol de segmentos."},
{title:"Contar el costo completo",body:"La descomposición y el arreglo necesitan O(n) tiempo y memoria. Hay O(log n) intervalos por camino; si cada consulta de intervalo cuesta O(log n), la consulta completa cuesta O(log²n). Cambiar un valor puntual cuesta O(log n). No olvides multiplicar los dos costos al analizar una consulta.\n\nComprueba un camino dentro de una sola cadena, otro que una dos ramas y uno con u=v. También prueba cambios en la raíz y valores negativos. Para pesos de aristas, u=v representa un camino vacío y su suma debe ser cero."}
],"¿Por qué un camino hacia la raíz cruza solo O(log n) aristas ligeras?",['Todos los vértices tienen dos hijos','El tamaño del subárbol al bajar por una ligera se reduce al menos a la mitad','Las cadenas tienen longitud fija'],1,"Al bajar por una arista ligera, el subárbol tiene como máximo la mitad del tamaño anterior. Solo puedes reducir un tamaño n a la mitad O(log n) veces antes de llegar a uno."),
P('centroid','Descomposición por centroides',['usaco-gold-dp-trees','usaco-plat-binary-jump'],["Separar el árbol en componentes de a lo sumo la mitad","Consultar distancias a vértices que se activan"],[
{title:"Buscar la estación activa más cercana",body:"En un árbol hay estaciones que se van activando. Desde cualquier vértice quieres consultar la distancia hasta la estación activa más cercana. Recorrer el árbol completo en cada pregunta cuesta O(n); guardar distancias entre todas las parejas ocupa O(n²). Podemos reducir ambas cantidades eligiendo unas pocas referencias por vértice."},
{title:"Una referencia que divide el árbol",body:"Un centroide es un vértice cuya eliminación deja componentes con a lo sumo la mitad de los vértices. En la cadena 1–2–3–4–5, el vértice 3 es centroide: quedan dos componentes de tamaño dos. Repite la división dentro de cada componente restante.\n\nLos centroides elegidos forman otro árbol, llamado árbol de descomposición. Cada vértice tiene O(log n) ancestros en él, porque el tamaño de su componente se reduce al menos a la mitad en cada nivel. Sus aristas no son necesariamente aristas del árbol original."},
{title:"Qué distancia guarda cada referencia",body:"Para cada vértice v guarda sus centroides ancestros y la distancia original hasta cada uno. Cada centroide c mantiene mejor[c], la menor distancia recibida desde una estación activa de su componente. Al activar x, recorre sus pares (c,d) y actualiza mejor[c]=min(mejor[c],d).\n\nEn la cadena de cinco vértices, activar 1 deja mejor[3]=2. Consultar desde 5 prueba dist(5,3)+mejor[3]=2+2=4. También examina sus otras referencias y toma la menor candidata finita. Si no hay ninguna, todavía no existen estaciones activas."},
{title:"Costo y comprobaciones de la implementación",body:"Preparar las listas cuesta O(n log n) tiempo y memoria. Con distancias precalculadas, activar y consultar cuestan O(log n). Si calculas cada distancia mediante LCA durante la operación, debes contar también ese costo.\n\nEn un árbol sin pesos, la distancia es el número de aristas; con pesos no negativos, utiliza la suma de pesos. Comprueba una consulta sin activos, una estación consultándose a sí misma y dos estaciones que empaten. Esos casos revisan el valor inicial, la distancia cero y la forma de combinar los mínimos."}
],"Una cadena tiene siete vértices. Al quitar el del centro, ¿de qué tamaños quedan las componentes?",['1 y 5','2 y 4','3 y 3'],2,"El centro deja tres vértices a cada lado. Ambas componentes tienen tamaño 3, menor que la mitad de los siete originales."),
P('VT',"Árboles virtuales para consultas con pocas marcas",['usaco-gold-tree-euler','usaco-plat-binary-jump'],["Conservar las marcas y sus puntos de encuentro","Guardar la información de las cadenas comprimidas"],[
{title:"Conectar pocos vértices de un árbol grande",body:"Un árbol puede tener doscientos mil vértices y recibir una pregunta sobre solo diez. Si la pregunta depende de cómo se conectan esos diez, recorrer todo el árbol en cada consulta repite trabajo innecesario. Queremos conservar los vértices marcados y las bifurcaciones de sus caminos, comprimiendo los tramos intermedios. Ese árbol reducido se llama árbol virtual."},
{title:"Identificar los puntos de encuentro",body:"Supón las aristas 1–2, 1–3, 2–4, 2–5 y 3–6, con raíz 1, y marca {4,5,6}. Los caminos de 4 y 5 se encuentran en 2; para conectarlos con 6 también necesitas 1. Conserva entonces {1,2,4,5,6}.\n\nEl vértice 3 está en un tramo sin bifurcaciones relevantes. Puedes sustituir 1–3–6 por una arista virtual de longitud 2. Así mantienes las distancias entre marcados sin guardar todos los vértices que atraviesan sus caminos."},
{title:"Preparar la información del árbol original",body:"Precalcula profundidad, tiempos de entrada y salida de DFS y una estructura de LCA. LCA(u,v) es el ancestro común más bajo. Un vértice u es ancestro de v si tin[u]≤tin[v] y tout[v]≤tout[u].\n\nLos tiempos permiten ordenar por posición en el recorrido y comprobar relaciones de ancestro. Las profundidades dan la longitud de una arista virtual u→v como profundidad[v]−profundidad[u]. Con aristas ponderadas utiliza, en su lugar, la diferencia de las distancias desde la raíz."},
{title:"Costo por consulta y casos pequeños",body:"Con LCA mediante saltos binarios, preparar el árbol cuesta O(n log n). Una consulta con k marcas necesita O(k log k+k log n) tiempo para ordenar y hallar LCAs, y O(k) espacio adicional. Si LCA es constante, domina la ordenación.\n\nComprueba dos marcas donde una sea ancestro de la otra, marcas en ramas distintas y una sola marca. Después compara las distancias entre marcas en el árbol original y en el virtual. Deben coincidir incluso cuando una arista virtual sustituya una cadena larga."}
],"Si partes de k≥1 vértices marcados y agregas los LCAs necesarios, ¿cuál es la cota del número de vértices retenidos?",['A lo sumo k²','A lo sumo 2k−1','Siempre exactamente n'],1,"Las k marcas tienen k−1 parejas consecutivas en orden DFS. Agregar sus LCAs incorpora como máximo k−1 vértices nuevos, así que quedan a lo sumo 2k−1 después de quitar repetidos."),
P('kruskal-tree','Árbol de reconstrucción de Kruskal',['usaco-gold-mst','usaco-plat-binary-jump'],["Guardar las fusiones de componentes como nodos","Responder el menor umbral de conexión usando ancestros"],[
{title:"Preguntar qué nivel de carretera necesitas",body:"Las ciudades 1, 2 y 3 tienen carreteras de niveles 3, 7 y 10: 1–2 usa nivel 3, 2–3 nivel 7 y 1–3 nivel 10. Si solo puedes usar carreteras de nivel≤W, ¿cuál es el menor W que conecta 1 con 3? Basta W=7, tomando el camino por 2. Queremos responder muchas preguntas de este tipo."},
{title:"Guardar las uniones que hace Kruskal",body:"Ordena las aristas por peso creciente, como en Kruskal, y utiliza DSU para mantener componentes. Al unir componentes distintas, crea un nuevo nodo que tenga como hijos sus dos raíces de reconstrucción y como etiqueta el peso de la arista.\n\nEn el ejemplo, la primera unión crea un padre de etiqueta 3 para las hojas 1 y 2. La segunda crea un padre de etiqueta 7 para ese grupo y la hoja 3. La arista de peso 10 no une grupos distintos y se descarta."},
{title:"Leer una respuesta en el historial",body:"Los vértices originales son hojas. El ancestro común más bajo de dos hojas representa la primera unión que las reunió; su etiqueta es el menor umbral que permite conectarlas. Para 1 y 3, esa etiqueta es 7.\n\nLa respuesta minimiza el mayor peso usado en un camino. No minimiza la suma. Un camino con pesos 5 y 5 tiene máximo 5 y suma 10; una arista directa de peso 8 tiene máximo y suma 8. Los dos objetivos escogerían caminos distintos."},
{title:"Costo y comprobación del resultado",body:"Ordenar cuesta O(m log m); DSU añade O(m α(n)) y preparar LCA cuesta O(n log n). Cada consulta con saltos binarios cuesta O(log n). El bosque ocupa O(n) nodos y la tabla de saltos O(n log n) memoria.\n\nEn grafos pequeños puedes comprobar una respuesta w filtrando las aristas de peso≤w y ejecutando una búsqueda. El par debe quedar conectado; con el siguiente peso menor disponible, debe quedar separado. Añade pruebas con pesos empatados, vértices aislados y consultas de una hoja consigo misma."}
],"Hay aristas 0–1 de peso 2, 1–2 de peso 5 y 0–2 de peso 9. ¿Cuál es el menor umbral que conecta 0 con 2?",['2','5','7','9'],1,"Con umbral 5 puedes recorrer 0–1–2. Con cualquier umbral menor, ninguna arista disponible llega a 2 desde ese grupo, así que 5 es el mínimo."),
P('geo-pri',"Geometría con vectores y orientación",['usaco-bronze-rect-geo'],["Decidir el sentido de un giro sin calcular pendientes","Comprobar colinealidad y el tamaño de los productos"],[
{title:"Decidir de qué lado queda un punto",body:"Caminas de A=(0,0) a B=(4,0) y quieres saber si C=(1,3) queda a tu izquierda o derecha. Podrías calcular ángulos, pero introduces decimales y casos especiales. Basta restar coordenadas y observar el signo de un producto.\n\nUn vector describe un desplazamiento: B−A=(4,0) y C−A=(1,3). Su producto cruzado es 4·3−0·1=12. Es positivo, así que C queda a la izquierda de la dirección A→B."},
{title:"Definir las operaciones que vamos a usar",body:"Para u=(ux,uy) y v=(vx,vy), el producto punto es u·v=ux·vx+uy·vy. Si los vectores no son nulos, su signo distingue ángulos agudos, rectos y obtusos. Además, u·u es la longitud al cuadrado, útil para comparar distancias sin raíces.\n\nEl producto cruzado en dos dimensiones es u×v=ux·vy−uy·vx. Su signo distingue giro antihorario, colinealidad y giro horario. Su valor absoluto mide el área del paralelogramo determinado por ambos vectores."},
{title:"Pasar de vectores a orientación y área",body:"Para orientar tres puntos utiliza orient(A,B,C)=(B−A)×(C−A). Restar A hace que el resultado no cambie si trasladas toda la figura. En el ejemplo vale 12; el área del triángulo ABC es la mitad, 6. Intercambiar B y C cambia el signo, pero no el área.\n\nUna orientación cero significa que los tres puntos están en una misma recta. No significa que C pertenezca al segmento AB: también debe quedar entre sus extremos. Esta distinción será necesaria para detectar contactos entre segmentos.",code:'#include <iostream>\n#include <cstdlib>\nusing namespace std;\nint main(){long long ax,ay,bx,by,cx,cy;cin>>ax>>ay>>bx>>by>>cx>>cy;long long z=(bx-ax)*(cy-ay)-(by-ay)*(cx-ax);cout<<(z>0?"ANTIHORARIO":z<0?"HORARIO":"COLINEAL")<<"\\n"<<llabs(z)<<"\\n";}'},
{title:"Casos que distinguen una implementación correcta",body:"Orientar tres puntos e intersectar dos segmentos cuestan O(1) tiempo y memoria. Lo que requiere atención son los casos geométricos: verticales, puntos repetidos, extremos compartidos y segmentos colineales separados. La intersección de cajas por sí sola no demuestra un cruce.\n\nPrueba (0,0),(2,2),(5,5): son colineales, pero el tercero no pertenece al segmento de los dos primeros. Decide también si los segmentos son cerrados. Si sus extremos son abiertos, un contacto solo en un extremo ya no cuenta y la prueba debe ajustarse a esa definición."}
],"Para A=(0,0), B=(4,0) y C=(1,3), ¿cuál es el área del triángulo ABC?",['3','6','12','24'],1,"El producto cruzado de (4,0) y (1,3) es 12. Su valor absoluto es el doble del área, por lo que el área vale 6."),
P('sweep-line',"Barrido para medir áreas cubiertas",['usaco-plat-range-sweep','usaco-plat-rurq','usaco-plat-geo-pri'],["Calcular el área de unión de rectángulos","Mantener longitudes reales cuando los intervalos se superponen"],[
{title:"Medir el área sin contar dos veces un cruce",body:"Dos rectángulos son [0,3]×[0,2] y [2,5]×[1,3]. Cada uno tiene área 6, pero sumarlas da 12 y cuenta dos veces el cuadrado compartido. Para muchos rectángulos, calcular todas las intersecciones se complica. Podemos medir la unión cortando la figura en franjas verticales."},
{title:"Buscar dónde cambia la altura cubierta",body:"Mueve una línea vertical de izquierda a derecha. El conjunto de rectángulos que atraviesa cambia solo en sus bordes verticales. Entre dos coordenadas x consecutivas, los intervalos y activos permanecen iguales y su unión tiene una longitud constante.\n\nEn el ejemplo, las franjas son [0,2), [2,3) y [3,5). Sus longitudes verticales cubiertas son 2, 3 y 2. Multiplicando por sus anchos obtienes áreas 4, 3 y 4: en total, 11."},
{title:"Convertir cada rectángulo en dos eventos",body:"El rectángulo [x1,x2]×[y1,y2] genera un alta en x1 y una baja en x2 del intervalo [y1,y2). Los bordes no tienen área, por lo que la convención semiabierta no cambia el resultado.\n\nAntes de aplicar los eventos de una coordenada x, suma longitudCubierta·(x−xAnterior). La estructura aún describe la franja que acabas de atravesar. Después incorpora las altas y bajas. Agrupar eventos de igual x resulta cómodo; procesarlos por separado también funciona si los anchos intermedios son cero."},
{title:"Costo y pruebas con distancias desiguales",body:"Hay dos eventos por rectángulo. Ordenar y actualizar el árbol cuesta O(n log n) tiempo y O(n) memoria. La longitud cubierta se consulta en la raíz en O(1).\n\nPrueba rectángulos idénticos, rectángulos que solo comparten borde y coordenadas muy separadas. Si Y=[0,90,100,110], los tres espacios miden 90, 10 y 10; contarlos como tres unidades produciría un área equivocada. Estos casos comprueban tanto los contadores como el uso de longitudes geométricas."}
],"¿Qué área cubren juntos [0,3]×[0,2] y [2,5]×[1,3]?",['10','11','12','13'],1,"Cada rectángulo mide 6 y comparten un cuadrado de área 1. La unión vale 6+6−1=11; las franjas también suman 4+3+4."),
P('convex-hull',"Envolvente convexa de puntos",['usaco-plat-geo-pri','usaco-silver-sorting-custom'],["Construir las dos cadenas del borde","Elegir si conservar puntos alineados sobre los lados"],[
{title:"Encontrar las esquinas que rodean los puntos",body:"Coloca puntos en las cuatro esquinas de un cuadrado de lado 2 y otro en su centro (1,1). Una liga estirada alrededor de ellos toca las cuatro esquinas; el punto central no cambia su forma. La región encerrada es la envolvente convexa: el menor conjunto convexo que contiene todos los puntos.\n\nAntes de construirla, decide qué salida necesitas: únicamente sus esquinas o todos los puntos de entrada que estén sobre el borde. Esa decisión cambia cómo tratar los puntos alineados."},
{title:"Ordenar para construir dos cadenas",body:"Ordena los puntos por x y después por y, y elimina duplicados. Construye la parte inferior recorriendo ese orden y la superior recorriéndolo al revés. Cada cadena se guarda en una pila; solo sus últimos puntos pueden entrar en conflicto con el nuevo.\n\nUsaremos la política de conservar solo esquinas. Si hay un único punto distinto, la respuesta es ese punto. Si todos están alineados, conserva los dos extremos. No necesitas pendientes ni intersecciones: las decisiones usan productos cruzados."},
{title:"Decidir cuándo quitar el último punto",body:"Al añadir p, llama a y b a los dos últimos puntos de la pila. Si orient(a,b,p)≤0, retira b y vuelve a comprobar. Después agrega p. Con esa condición, la cadena inferior conserva giros antihorarios; el caso cero quita puntos intermedios de un borde recto.\n\nPor ejemplo, al procesar (0,0),(1,0),(2,0), el punto (1,0) desaparece: la conexión directa entre los extremos describe el mismo borde. Un punto retirado de la cadena inferior aún podría aparecer en la superior."},
{title:"Comprobar la política del borde",body:"Prueba un único punto, puntos repetidos y una colección completamente colineal. Luego añade (1,0) al cuadrado inicial: la figura no cambia, pero la lista cambia si piden todos los puntos del borde.\n\nUna comprobación útil es revisar que cada giro de la envolvente de esquinas tenga el signo esperado y que todos los puntos queden dentro o sobre ella. También puedes contrastar el área de figuras conocidas. Estas pruebas detectan errores de desigualdad, de unión de cadenas y de orden de los vértices."}
],"Si la salida pide solo esquinas, ¿qué puntos quedan de (0,0), (1,0) y (2,0)?",['Los tres puntos','Solo (1,0)','Los dos extremos'],2,"Quedan los dos extremos. El punto (1,0) está sobre el segmento que los une y no forma una esquina adicional."),
P('convex-hull-trick',"Optimizar una DP con rectas",['usaco-gold-intro-dp','usaco-plat-geo-pri'],["Convertir transiciones en consultas de mínimo entre rectas","Comprobar el orden de pendientes y consultas"],[
{title:"Una transición que compara muchas opciones",body:"Para calcular dp[i]=min(j<i){dp[j]+(h[i]−h[j])²+C}, puedes probar todos los j anteriores. Eso cuesta O(n²) para n estados. Antes de buscar una estructura, expande el cuadrado: dp[i]=h[i]²+C+min(j<i){(−2h[j])·h[i]+dp[j]+h[j]²}.\n\nCada j aporta una recta m·x+b, con m=−2h[j] y b=dp[j]+h[j]². El estado i consulta el mínimo de esas rectas en x=h[i]. La parte h[i]²+C se suma después."},
{title:"Una recta puede ganar solo en cierto intervalo",body:"Compara f(x)=2x+1 y g(x)=−x+10. En x=2 dan 5 y 8; en x=5 dan 11 y 5. Se cruzan en x=3: antes gana f y después g. La envolvente inferior describe el menor valor entre todas las rectas para cada x.\n\nNo hace falta conservar una recta que nunca mejora ese mínimo. Convex hull trick organiza las rectas que sí pueden ganar y permite consultar esa envolvente sin evaluar todas las opciones."},
{title:"Comprobar el orden antes de usar una deque",body:"Para mínimos, una deque funciona si insertas pendientes decrecientes y consultas valores x no decrecientes. Cuando h crece estrictamente en la DP anterior, las pendientes −2h[j] decrecen y las consultas h[i] crecen: ambas condiciones se cumplen.\n\nConsulta primero y después inserta la recta de i, porque solo son válidos los candidatos j<i. No reordenes los estados para obtener monotonía si eso altera sus dependencias. Si h llega en otro orden, la transformación algebraica sigue siendo correcta, pero necesitas otra estructura, como Li Chao."},
{title:"Qué hacer cuando una condición no se cumple",body:"Con pendientes ordenadas y consultas arbitrarias, conserva la envolvente y busca la mejor recta por binaria en O(log n). No destruyas su frente: una consulta que vuelva a un x menor podría necesitarlo. Para inserciones sin orden, considera Li Chao u otro contenedor adecuado.\n\nAntes de optimizar una DP, evalúa todas las rectas en casos pequeños. Con h=[0,2,5], C=1 y dp[0]=0, obtienes dp[1]=5 y dp[2]=min(26,15)=15. La versión rápida debe respetar los mismos candidatos y producir esos valores."}
],"¿Cuándo puedes retirar definitivamente rectas del frente de una deque que responde mínimos?",['Siempre que las funciones sean rectas','Cuando pendientes y consultas siguen órdenes monótonos compatibles','Solo cuando todos los interceptos son cero'],1,"Para la variante explicada, las pendientes llegan decrecientes y las consultas x no disminuyen. Una recta que pierde frente a la siguiente no volverá a ganar en las consultas futuras."),
P('PIE','Principio de inclusión y exclusión',['usaco-gold-combo','usaco-silver-intro-bitwise'],["Corregir repeticiones entre conjuntos","Calcular intersecciones para combinar sus cantidades"],[
{title:"Contar números que cumplen alguna condición",body:"Entre 1 y 30 hay 15 múltiplos de 2 y 10 de 3. Sumarlos da 25, pero los múltiplos de 6 aparecen en ambas listas. Son cinco, así que la unión contiene 15+10−5=20 números. Inclusión y exclusión corrige esas repeticiones para contar cada objeto una sola vez."},
{title:"Qué cambia al añadir una tercera condición",body:"Añade los múltiplos de 5: son seis. Resta los cruces por parejas, que son múltiplos de 6, 10 y 15. Ahora el número 30 fue sumado tres veces y restado tres, por lo que debes reponerlo.\n\nLa cuenta queda 15+10+6−5−3−2+1=22. El complemento contiene 30−22=8 números que no son divisibles por ninguno de los tres. La pregunta debe distinguir entre cumplir al menos una condición y no cumplir ninguna."},
{title:"Escribir y justificar la fórmula general",body:"Para conjuntos A1,…,Ak, recorre cada subconjunto no vacío S de condiciones. Si |S| es impar, suma el tamaño de su intersección; si es par, réstalo.\n\nUn objeto presente en t conjuntos aparece con coeficiente C(t,1)−C(t,2)+…+(−1)^(t+1)C(t,t). La expansión de (1−1)^t muestra que ese coeficiente vale 1 para t≥1. Un objeto que no cumple ninguna condición nunca aparece. Así la fórmula cuenta exactamente la unión."},
{title:"Costo y seguridad de las cantidades",body:"Hay 2^k−1 máscaras y hasta k divisores por máscara. Incluyendo gcd, el costo directo es O(k·2^k·log D), con O(k) memoria. k debe ser pequeño; N puede ser grande porque no recorres sus enteros.\n\nEl tipo debe soportar las contribuciones con signo y sus sumas intermedias. Comprueba divisores mayores que N, un divisor igual a 1 y divisores no coprimos. Para 4 y 6 hasta 24, el resultado debe ser 6+4−2=8."}
],"Entre 1 y 30, ¿cuántos números son divisibles por 2, por 3 o por ambos?",['15','20','25','30'],1,"Hay 15 múltiplos de 2 y 10 de 3. Los 5 múltiplos de 6 aparecen dos veces; al restar esa copia sobrante obtienes 15+10−5=20."),
P('matrix-expo',"Potencias de matrices y recurrencias",['usaco-gold-modular','usaco-gold-intro-dp'],["Representar una transición con coeficientes","Repetir una transición usando exponenciación binaria"],[
{title:"Avanzar en una sucesión sin recorrer cada término",body:"Fibonacci cumple F(t+2)=F(t+1)+F(t). Si guardas la pareja [F(t+1),F(t)], el siguiente estado es [F(t+1)+F(t),F(t+1)]. Para n pequeño puedes repetir esa operación; para n enorme queremos agrupar muchos pasos.\n\nUna matriz guarda los coeficientes de esa transformación. Aquí T=[[1,1],[1,0]] y usamos vectores columna: el estado siguiente es T por el estado actual."},
{title:"Comprobar qué guarda cada componente",body:"Desde [1,0], una aplicación da [1,1], dos dan [2,1] y cinco dan [8,5]. La segunda componente de T^n·[1,0] es F(n). Esta traza fija la orientación antes de escribir la multiplicación.\n\nCon vectores columna, aplicar A y después B produce B·A·v. La multiplicación es asociativa, pero en general no conmutativa. Puedes agrupar operaciones sin cambiar su resultado, aunque no puedas invertir su orden."},
{title:"Construir estados para otras recurrencias",body:"Para una recurrencia lineal de orden d, guarda d valores consecutivos. La primera fila de la matriz contiene los coeficientes de la recurrencia y las demás desplazan las componentes. La misma matriz debe describir cada paso.\n\nUn término constante se representa añadiendo una componente fija igual a uno. Por ejemplo, xSiguiente=2x+3 usa [[2,3],[0,1]] sobre [x,1]. Una regla como xSiguiente=x·y no es lineal en [x,y] y no cabe directamente en este modelo de coeficientes fijos.",code:'#include <iostream>\n#include <array>\nusing namespace std;\nusing M=array<array<long long,2>,2>;const long long MOD=1000000007;\nM mul(M a,M b){M c{};for(int i=0;i<2;i++)for(int j=0;j<2;j++)for(int k=0;k<2;k++)c[i][j]=(c[i][j]+a[i][k]*b[k][j])%MOD;return c;}\nint main(){unsigned long long n;cin>>n;M r{{{1,0},{0,1}}},a{{{1,1},{1,0}}};while(n){if(n&1)r=mul(r,a);a=mul(a,a);n>>=1;}cout<<r[1][0]<<"\\n";}'},
{title:"Verificar estados, orden y exponente cero",body:"Compara las potencias 0, 1 y 2 con cálculos manuales. Para Fibonacci, F(0)=0 y F(10)=55 comprueban el estado inicial y la potencia elegida. Multiplicar matrices que no conmuten también ayuda a detectar una inversión de orden.\n\nSi la transición cambia con el tiempo, no puedes elevar una única matriz sin modelar esa variación. Escribe primero la regla exacta de cada paso; la exponenciación solo acelera una composición que ya representa correctamente el problema."}
],"Si aplicas una transición cero veces, ¿qué matriz representa el resultado?",['La matriz cero','La matriz identidad','La propia matriz de transición'],1,"La identidad conserva cualquier estado: I·v=v. Por eso es el resultado inicial de la exponenciación y también responde al exponente cero."),
P('bitsets',"Bitsets para procesar estados booleanos",['usaco-silver-intro-bitwise','usaco-gold-knapsack'],["Expresar varias transiciones con operaciones de bits","Justificar qué estados puedes descartar al desplazar"],[
{title:"Guardar qué sumas son posibles",body:"Tienes objetos de pesos 2 y 3 y puedes usar cada uno a lo sumo una vez. Las sumas posibles son {0,2,3,5}. Representa cada suma s con un bit: uno si puedes conseguirla y cero si no. Antes de procesar objetos, solo está encendido el bit cero, por el subconjunto vacío."},
{title:"Mover todos los estados con un desplazamiento",body:"Si B guarda las sumas anteriores y llega un objeto de peso x, B<<x representa las sumas que lo usan. Las que no lo usan siguen en B. Por eso la transición es B=B OR (B<<x), escrita en C++ como B |= B << x.\n\nEl desplazamiento se calcula desde el estado anterior antes de asignar. Así cada objeto se utiliza cero o una vez; no estamos permitiendo repetirlo indefinidamente."},
{title:"Seguir objetos distintos con el mismo peso",body:"Con [2,3,2], los conjuntos evolucionan como {0}, {0,2}, {0,2,3,5} y {0,2,3,4,5,7}. La suma 4 utiliza los dos objetos distintos de peso 2. La suma 6 sigue siendo imposible.\n\nEste ejemplo ayuda a distinguir objetos repetidos de usos repetidos de un mismo objeto. OR conserva la existencia de una suma, incluso si varias selecciones distintas llegan a ella.",code:'#include <iostream>\n#include <bitset>\nusing namespace std;\nint main(){const int LIMIT=100000;int n,target;cin>>n>>target;bitset<LIMIT+1>b;b[0]=1;while(n--){int x;cin>>x;if(x<0)return 0;b|=(b<<x);}if(target<0||target>LIMIT)return 0;cout<<(b[target]?"SI":"NO")<<"\\n";}'},
{title:"Costo y casos que comprueban la transición",body:"Con n objetos y S estados, el modelo por palabras usa O(n·ceil(S/w)) operaciones y O(S) bits de memoria. La cantidad de estados matemáticos sigue siendo S; el ahorro viene de procesarlos agrupados.\n\nPrueba peso cero, objetivo cero, pesos repetidos y el objetivo máximo admitido. La suma cero debe seguir posible por la selección vacía. Para una lista pequeña, enumera todos los subconjuntos y compara los bits; así puedes detectar tanto usos múltiples incorrectos como límites mal dimensionados."}
],"Con un objeto de peso 2 y otro de peso 3, utilizables una vez cada uno, ¿qué sumas puedes formar?",['{0,2,3,5}','{2,3}','{0,1,2,3,4,5}'],0,"Puedes no elegir objetos y obtener 0, elegir uno y obtener 2 o 3, o elegir ambos y obtener 5. No puedes repetir el mismo objeto para formar 4."),
P('DC-DP',"Optimizar filas de DP con divide y vencerás",['usaco-gold-dp-ranges','usaco-silver-prefix-sums'],["Demostrar que los cortes óptimos no retroceden","Reducir los candidatos de cada mitad de una fila"],[
{title:"Elegir dónde termina cada grupo",body:"Divide [1,2,3] en dos segmentos contiguos no vacíos. Si cada segmento cuesta el cuadrado de su suma, cortar después del primer elemento cuesta 1²+5²=26; cortar después del segundo cuesta 3²+3²=18. Para un arreglo grande y K grupos, queremos encontrar todos los cortes sin enumerar cada partición."},
{title:"Escribir primero la programación dinámica",body:"Define dp[k][i] como el menor costo para dividir los primeros i elementos en k segmentos. Si el último empieza después de j, su costo es (S[i]−S[j])², donde S guarda sumas prefijas. Entonces dp[k][i]=min(k−1≤j<i){dp[k−1][j]+(S[i]−S[j])²}.\n\nEl límite j≥k−1 deja espacio para los grupos anteriores y j<i mantiene el último no vacío. La solución directa cuesta O(Kn²), con cada costo evaluado en O(1)."},
{title:"La propiedad que permite reducir candidatos",body:"Para una fila fija, llama opt[i] al menor corte que alcanza su mínimo. La optimización requiere opt[i]≤opt[i+1]: al extender el prefijo, el corte elegido no retrocede. No todas las DP cumplen esa condición.\n\nSi conoces el mejor corte de una posición central, la monotonía permite limitar los candidatos de las posiciones a su izquierda y derecha. Antes de programar esa búsqueda reducida, hay que justificar la monotonía para el costo concreto."},
{title:"Comparar con la recurrencia sin optimizar",body:"La versión O(Kn²) sirve para verificar casos pequeños. Compara tanto los costos como los cortes elegidos e incluye ceros y K=n, donde cada segmento tiene un elemento.\n\nQue algunas pruebas tengan cortes ordenados no demuestra la propiedad para otro costo. Si cambias la función o las restricciones, vuelve a comprobar la desigualdad usada. Con A=−2 y C=4, la diferencia 2AC es negativa; ese ejemplo muestra exactamente dónde falla la justificación basada en no negatividad."}
],"Después de resolver el centro de una fila, ¿qué permite limitar los candidatos de las posiciones de su izquierda?",['Todos los costos son positivos','Los cortes óptimos son monótonos respecto al extremo derecho','El arreglo está ordenado por valor'],1,"Si los cortes óptimos no disminuyen al aumentar la posición, cualquier óptimo a la izquierda está como máximo en el corte del centro. Esa propiedad justifica excluir los candidatos mayores."),
P('dp-sos',"Sumas de subconjuntos con la transformada SOS",['usaco-gold-dp-bitmasks'],["Reutilizar sumas al procesar un bit cada vez","Evitar enumerar todas las parejas de máscara y submáscara"],[
{title:"Contar conjuntos contenidos en otro",body:"Representa dos habilidades con dos bits. Las máscaras 00, 01, 10 y 11 significan ninguna, la primera, la segunda y ambas. Si sus frecuencias son [1,2,3,4], consultar 10 debe contar 00 y 10: en total 4. Consultar 11 debe contar las cuatro categorías: 10.\n\nEn general queremos F[mask]=Σ(sub⊆mask)A[sub]. La relación es inclusión de bits, no contigüidad como en un subarreglo."},
{title:"Evitar enumerar cada subconjunto de nuevo",body:"Podrías enumerar todas las submáscaras de cada máscara. El total cuesta O(3^B): cada bit está fuera de mask, dentro de mask pero fuera de sub, o dentro de ambos.\n\nSOS DP reutiliza sumas parciales y reduce el costo a O(B·2^B). Procesamos un bit a la vez, permitiendo que se conserve o se omita. No necesitamos ordenar por cantidad de bits encendidos."},
{title:"La actualización de una dimensión",body:"Copia A en F. Para cada bit i, recorre todas las máscaras; cuando mask contiene i, agrega F[mask sin i] a F[mask]. Si no lo contiene, déjala igual.\n\nCon A=[1,2,3,4], procesar el bit 0 deja [1,3,3,7]. Procesar el bit 1 deja [1,3,4,10]. El valor final de 10 es 1+3 y el de 11 es 1+2+3+4, como pedía la pregunta.",code:'#include <iostream>\n#include <vector>\nusing namespace std;\nint main(){int k;cin>>k;if(k<0||k>20)return 0;int n=1<<k;vector<long long>f(n);for(auto&x:f)cin>>x;for(int b=0;b<k;b++)for(int mask=0;mask<n;mask++)if(mask&(1<<b))f[mask]+=f[mask^(1<<b)];for(auto x:f)cout<<x<<" ";cout<<"\\n";}'},
{title:"Tiempo, memoria y comprobaciones",body:"Hay B pasadas sobre 2^B máscaras: O(B·2^B) tiempo y O(2^B) memoria. Con B=20, un vector de long long tiene 1048576 entradas y ocupa unos 8 MiB; si guardas varios, suma sus tamaños.\n\nPara verificar, enumera submáscaras directamente con pocos bits y compara. Incluye la máscara vacía, una máscara con un solo bit y la máscara completa. Comprueba además que las sumas caben en el tipo, aunque cada frecuencia inicial sea pequeña."}
],"Las máscaras 00, 01, 10 y 11 tienen valores 1, 2, 3 y 4. ¿Cuánto suma F[11] sobre sus submáscaras?",['4','7','9','10'],3,"Las cuatro máscaras están contenidas en 11. Por eso F[11]=1+2+3+4=10."),
P('plat-conclusion',"Combinar barridos, árboles y programación dinámica",['usaco-plat-hld','usaco-plat-convex-hull-trick','usaco-plat-dc-dp','usaco-plat-dp-sos'],["Justificar cómo se conectan dos estructuras","Comprobar las condiciones que necesita una optimización"],[
{title:"Combinar técnicas a partir de una pregunta",body:"Una red tiene carreteras con dificultad w. Cada consulta da una ciudad v y un límite W, y pide cuántas ciudades puedes alcanzar usando solo carreteras con w≤W. Ejecutar una búsqueda por consulta funciona, pero cuesta O(q(n+m)). Antes de elegir una estructura, observa qué cambia cuando aumenta W: se permiten más aristas y ninguna deja de estar permitida."},
{title:"Reordenar para no repetir las búsquedas",body:"Si las consultas se conocen de antemano y son independientes, ordénalas por W. Ordena también las aristas por w. Mantén un puntero e incorpora cada arista cuando su peso pasa a estar permitido.\n\nUn DSU guarda las componentes y sus tamaños. La respuesta de una consulta es el tamaño de la componente de v. Conserva el índice original de cada consulta para devolver las respuestas en el orden de entrada."},
{title:"Seguir un ejemplo antes de programar",body:"En el camino 1–2 de peso 3 y 2–3 de peso 7, consultar desde 1 con W=2 da 1; con W=3 da 2; con W=7 da 3. Consultar desde 3 con W=3 da 1.\n\nSi los límites llegan como 7,2,3, procésalos como 2,3,7, pero guarda cada respuesta en su posición original. Las ciudades alcanzables incluyen siempre el vértice de partida, incluso cuando ninguna carretera está abierta."},
{title:"Revisar una solución completa",body:"Antes de dar por terminada una solución, comprueba definición de estados, casos iniciales, transiciones y forma de obtener la respuesta. Cuenta el costo de todas las capas: una consulta de árbol que ejecuta varias consultas de rango puede multiplicar factores logarítmicos.\n\nExplica después el procedimiento sin apoyarte en el código. Si no queda claro por qué una estructura recibe exactamente los datos de una consulta, vuelve a ese punto del argumento. Los ejercicios siguientes usan el barrido de conectividad y dos propuestas donde falta una condición."}
],"Antes de reordenar estados de una DP para usar una estructura de rectas, ¿qué debes demostrar?",['Que los nombres de variables sean cortos','Que se conservan las dependencias y las transiciones permitidas','Que todos los valores caben en int'],1,"El nuevo orden debe conservar las dependencias y las transiciones permitidas. Si admite un estado futuro o elimina uno anterior válido, cambia el problema aunque facilite la estructura."),
];
